    }
    removeEventListener() {}
    callServerTool = bridge.callServerTool;
    connect = bridge.connect;
    getHostContext() { return { theme: "light" }; }
  },
  PostMessageTransport: class { close() {} },
}));
const parentDescriptor = Object.getOwnPropertyDescriptor(window, "parent");
const openAiDescriptor = Object.getOwnPropertyDescriptor(window, "openai");

